import java.util.*;

class Solution {
    private int[][] memo;
    private int[] minCost2;
    private int s1, s2;

    private int solve(int i, int mask, List<List<Integer>> cost) {
        if (i == s1) {
            int res = 0;
            for (int j = 0; j < s2; ++j) {
                if ((mask & (1 << j)) == 0) res += minCost2[j];
            }
            return res;
        }
        if (memo[i][mask] != -1) return memo[i][mask];
        int ans = (int)1e9;
        for (int j = 0; j < s2; ++j) {
            ans = Math.min(ans, cost.get(i).get(j) + solve(i + 1, mask | (1 << j), cost));
        }
        return memo[i][mask] = ans;
    }

    public int connectTwoGroups(List<List<Integer>> cost) {
        s1 = cost.size();
        s2 = cost.get(0).size();
        minCost2 = new int[s2];
        Arrays.fill(minCost2, (int)1e9);
        for (int j = 0; j < s2; ++j) {
            for (int i = 0; i < s1; ++i) {
                minCost2[j] = Math.min(minCost2[j], cost.get(i).get(j));
            }
        }
        memo = new int[s1 + 1][1 << s2];
        for (int[] row : memo) Arrays.fill(row, -1);
        return solve(0, 0, cost);
    }
}

