var connectTwoGroups = function(cost) {
    const s1 = cost.length, s2 = cost[0].length;
    const minCost2 = Array(s2).fill(Infinity);
    for (let j = 0; j < s2; ++j) {
        for (let i = 0; i < s1; ++i) {
            minCost2[j] = Math.min(minCost2[j], cost[i][j]);
        }
    }
    const memo = Array.from({ length: s1 + 1 }, () => Array(1 << s2).fill(-1));
    function solve(i, mask) {
        if (i === s1) {
            let res = 0;
            for (let j = 0; j < s2; ++j) {
                if (!(mask & (1 << j))) res += minCost2[j];
            }
            return res;
        }
        if (memo[i][mask] !== -1) return memo[i][mask];
        let ans = Infinity;
        for (let j = 0; j < s2; ++j) {
            ans = Math.min(ans, cost[i][j] + solve(i + 1, mask | (1 << j)));
        }
        return memo[i][mask] = ans;
    }
    return solve(0, 0);
};
